from ply.lex import TOKEN
from .message_query_function import get_registered_query_function
from .exceptions import MessageQueryTokenizerError


def find_function_in_registered_functions(function_name):
    """Registration done by decorator."""
    return get_registered_query_function(function_name)


reserved_keywords = {
    'fulfills': 'FULFILLS',
    'contains': 'CONTAINS',
    'not': 'NOT',
    'and': 'AND',
    'or': 'OR'
}


tokens = ['COMPARE_OPERATOR', 'EXISTENCE_OPERATOR', 'INTEGER_VALUE', 'STRING_VALUE',
          'FIELD_SELECTOR', 'FUNCTION_CALL', 'FUNCTION_ON_FIELD_CALL'] + list(reserved_keywords.values())


# reserved_keywords and EXISTENCE_OPERATOR tokens must be declared first to not take them as name for FIELD_SELECTOR
# PROBLEM: they can not appear as field names, what if such field appears inside tested message?
#           for such cases we may use buildin function:   field(and)


def t_EXISTENCE_OPERATOR(t):
    r"""is\s+not\s+present(?![\w\-])|is\s+present(?![\w\-])"""
    t.value = ' '.join(t.value.split())
    return t


# difference between  field identifier  and   string value  is in string bracing, so:
# we force string values in ''   like   'a'  or "a"
#    - then we can also compare field against field   or f(fieldA) vs  f(fieldB)

# [a-zA-Z][a-zA-Z\-\d]*  is simplified ASN.1 identifier
#                        - no check for starting lowercase letter, nor - at end, nor duplicated -- (not allowed)
#                         (maybe consider allowing underscore _)
field_selector_regexp = r'[a-zA-Z][a-zA-Z\-\d]*'
function_call_on_field_regexp = r'[a-zA-Z]\w*\(' + field_selector_regexp + r'\s*,?\s*[^\)]*\)'

# we do not allow function name to start from underscore, nor space between function name and opening brace
function_call_on_value_regexp = r'[a-zA-Z]\w*\([^\)]*\)'


@TOKEN(function_call_on_field_regexp)
def t_FUNCTION_ON_FIELD_CALL(t):
    """
    Same as t_FUNCTION_CALL but first parameter is FIELD_SELECTOR
    First param is value of field pointed by <field_selector>,
    may have second (optional) parameter.
    """
    parts = t.value.split('(')
    function_name = parts[0]
    function_parameter_string = ''
    parameters = parts[1][0:-1].split(',', 1)
    field_selector = parameters[0].strip()
    if len(parameters) > 1:
        function_parameter_string = parameters[1].strip()
        if (function_parameter_string[0] == '"') or (function_parameter_string[0] == "'"):
            function_parameter_string = function_parameter_string[1:]
        if (function_parameter_string[-1] == '"') or (function_parameter_string[-1] == "'"):
            function_parameter_string = function_parameter_string[:-1]
    function_object = find_function_in_registered_functions(function_name)
    t.value = {'name': function_name, 'field_selector': field_selector, 'parameter_string': function_parameter_string, 'function': function_object}
    return t


@TOKEN(function_call_on_value_regexp)
def t_FUNCTION_CALL(t):
    """
    Function call.

    :param t:
    :return: t
    """
    parts = t.value.split('(')
    function_name = parts[0]
    function_parameter_string = parts[1][0:-1].strip()
    if (function_parameter_string[0] == '"') or (function_parameter_string[0] == "'"):
        function_parameter_string = function_parameter_string[1:]
    if (function_parameter_string[-1] == '"') or (function_parameter_string[-1] == "'"):
        function_parameter_string = function_parameter_string[:-1]
    function_object = find_function_in_registered_functions(function_name)
    t.value = {'name': function_name, 'field_selector': None, 'parameter_string': function_parameter_string, 'function': function_object}
    return t


def t_COMPARE_OPERATOR(t):
    r"""==|!=|<=|>=|>|<|\beq\b|\bne\b|\ble\b|\bge\b|\bgt\b|\blt\b"""
    # r'==|!=|<=|>=|>|<'
    return t


@TOKEN(field_selector_regexp)
def t_FIELD_SELECTOR(t):
    """
    Field selector.

    example: S1AP-PDU137  DownlinkS1cdma2000tunneling  protocolIEs   maxNumberROHC-ContextSessions

    :param t:
    :return: t
    """
    t.type = reserved_keywords.get(t.value, 'FIELD_SELECTOR')  # Check for reserved words
    return t


def t_INTEGER_VALUE(t):
    r"""-?\d+"""
    t.value = int(t.value)
    return t


def t_STRING_VALUE(t):  # string braced in "..."
    r"""\"([^\\"]|(\\.))*\""""
    t.value = t.value[1:-1]
    return t


def t_STRING_VALUE_2(t):  # string braced in '...'
    r"""\'([^\\']|(\\.))*\'"""
    t.value = t.value[1:-1]
    t.type = 'STRING_VALUE'
    return t


literals = "(),"

t_ignore = ' \t'


# Define a rule so we can track line numbers
def t_newline(t):
    r"""\n+"""
    t.lexer.lineno += len(t.value)


def find_column(token):
    """
    Find column.

    :param token:
    :return: column
    """
    input_data = token.lexer.lexdata
    last_cr = input_data.rfind('\n', 0, token.lexpos)
    if last_cr < 0:
        last_cr = 0
    column = (token.lexpos - last_cr)
    return column


def line_where_occured(token):
    """
    Check line where token occured.

    :param token:
    :return: int
    """
    input_data = token.lexer.lexdata
    cr_before_token = input_data.rfind('\n', 0, token.lexpos)
    cr_after_token = input_data.find('\n', cr_before_token + 1)
    line_of_token = input_data[cr_before_token + 1:cr_after_token]
    return line_of_token


def t_error(t):
    """Error handling rule."""
    col = find_column(t)
    line_of_token = line_where_occured(t)
    raise MessageQueryTokenizerError(t.value[0], t.lexer.lineno, col, line_of_token, t.lexer.lexdata)


"""
Query language for asking message about its content


syntax EBNF:

query                           : composed_query
                                | simple_query
composed_query                  : braced_query
                                | negated_query
                                | and_or_query
braced_query                    : ( query )
negated_query                   : NOT query
and_or_query                    : query AND query
                                | query OR query
simple_query                    : comparator
                                | field_existence_checker
                                | substructure_checker
query_list                      : ( query_list_content )
query_list_content              : query
                                | query , query_list_content
comparator                      : field_vs_field_comparator
                                | field_vs_function_comparator
field_vs_field_comparator       : field_related_operand COMPARE_OPERATOR value_related_operand
field_existence_checker         : FIELD_SELECTOR EXISTENCE_OPERATOR
substructure_checker            : dict_checker
                                | list_checker
field_related_operand           : FIELD_SELECTOR
                                | FUNCTION_ON_FIELD_CALL
value_related_operand           : simple_value
                                | FUNCTION_CALL
field_vs_function_comparator    : FIELD_SELECTOR FULFILLS FUNCTION_CALL             # FUNCTION_CALL.value['field_selector'] = FIELD_SELECTOR.value
dict_checker                    : FIELD_SELECTOR CONTAINS query                     # field_selector must point to dict
list_checker                    : FIELD_SELECTOR CONTAINS query_list                # field_selector must point to list
simple_value                    : INTEGER_VALUE
                                | STRING_VALUE

"""  # pylint: disable=pointless-string-statement
